  "name": "query_graph",
  "arguments": {
    "sparql": "SELECT ?point WHERE { <http://example.org/buildings/8230> <br:hasPhysicalZone> ?zone . ?zone <http://example.org/types/zone> <br:Perimeter_mid_ZN_4> . OPTIONAL { ?point <http://example.org/rdfref#hasExternalReference> ?point . } OPTIONAL { ?point <http://example.org/rdfref#hasTimeseriesId> ?tsid . } . FILTER( bound(?tsid) ) . FILTER( NOT bound(?point) ) }"
